    "Batch Grade: Grade A (Export Quality)": "ಬ್ಯಾಚ್ ದರ್ಜೆ: ಗ್ರೇಡ್ ಎ (ರಫ್ತು ಗುಣಮಟ್ಟ)",
    "Manage crops, predict mandi prices, obtain agronomic guidance, and sell directly with zero middleman deductions.": "ಬೆಳೆಗಳನ್ನು ನಿರ್ವಹಿಸಿ, ಮಂಡಿ ಬೆಲೆ ಮುನ್ಸೂಚನೆ ಪಡೆಯಿರಿ, ಕೃಷಿ ಸಲಹೆಗಳನ್ನು ಆಲಿಸಿ ಮತ್ತು ಮಧ್ಯವರ್ತಿಗಳಿಲ್ಲದೆ ನೇರವಾಗಿ ಮಾರಾಟ ಮಾಡಿ.",
    "Discover verified farmer listings, compare APMC modal benchmarks, request bulk orders, and trade with locked escrow protection.": "ದೃಢೀಕೃತ ರೈತರ ಪಟ್ಟಿಯನ್ನು ನೋಡಿ, ರಾಜ್ಯದ ಎಪಿಎಂಸಿ ದರಗಳನ್ನು ಹೋಲಿಸಿ, ಸಗಟು ಖರೀದಿಗೆ ವಿನಂತಿಸಿ ಮತ್ತು ಸುರಕ್ಷಿತ ಎಸ್ಕ್ರೋ ಮೂಲಕ ಆರ್ಡರ್ ಮಾಡಿ.",
    "Supervise marketplace activities, verify farmer KYC & buyer licenses, audit disputes, and monitor AI model health.": "ಮಾರುಕಟ್ಟೆ ಚಟುವಟಿಕೆಗಳನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡಿ, ರೈತರ ಕೆವೈಸಿ ಮತ್ತು ಖರೀದಿದಾರರ ಪರವಾನಗಿ ಪರಿಶೀಲಿಸಿ, ಎಐ ಮಾದರಿಗಳನ್ನು ನಿಯಂತ್ರಿಸಿ.",
    "AI Agricultural Intelligence Showcase": "ಎಐ ಕೃಷಿ ಬುದ್ಧಿಮತ್ತೆ ಪ್ರದರ್ಶನ",
    "Our forecasting models calculate predictions from historical observations while Gemini explains them with complete transparency.": "ನಮ್ಮ ಮುನ್ಸೂಚನಾ ಮಾದರಿಗಳು ಐತಿಹಾಸಿಕ ಮಂಡಿ ದತ್ತಾಂಶದಿಂದ ಲೆಕ್ಕಾಚಾರ ಮಾಡುತ್ತವೆ ಮತ್ತು ಜೆಮಿನಿ ಅವುಗಳನ್ನು ಪಾರದರ್ಶಕವಾಗಿ ವಿವರಿಸುತ್ತದೆ.",
    "How AgriTech Works": "ಅಗ್ರಿಟೆಕ್ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ",
    "From planting through AI harvest guidance, verified listing, procurement, and automated escrow bank settlements.": "ಬಿತ್ತನೆಯಿಂದ ಹಿಡಿದು ಎಐ ಕೊಯ್ಲು ಮಾರ್ಗದರ್ಶನ, ದೃಢೀಕೃತ ಪಟ್ಟಿ, ಸಗಟು ಖರೀದಿ ಮತ್ತು ನೇರ ಬ್ಯಾಂಕ್ ಎಸ್ಕ್ರೋ ಪಾವತಿಯವರೆಗೆ ಸಂಪೂರ್ಣ ಹಂತಗಳು.",
    "Farmer Registers": "ರೈತರು ನೋಂದಾಯಿಸಿಕೊಳ್ಳುತ್ತಾರೆ",
    "Create a farmer profile with land acreage, soil type, and regional language preference.": "ಜಮೀನಿನ ವಿಸ್ತೀರ್ಣ, ಮಣ್ಣಿನ ವಿಧ ಮತ್ತು ಪ್ರಾದೇಶಿಕ ಭಾಷೆಯೊಂದಿಗೆ ಪ್ರೊಫೈಲ್ ರಚಿಸುತ್ತಾರೆ.",
    "Adds Crops & Harvests": "ಬೆಳೆ ವಿವರಗಳನ್ನು ಸೇರಿಸುತ್ತಾರೆ",
    "Log crop varieties, sowing dates, and expected yield windows into the farm management tracker.": "ಬೆಳೆಯ ತಳಿಗಳು, ಬಿತ್ತನೆ ದಿನಾಂಕಗಳು ಮತ್ತು ನಿರೀಕ್ಷಿತ ಇಳುವರಿಯನ್ನು ದಾಖಲಿಸುತ್ತಾರೆ.",
    "Receives AI Insights": "ಎಐ ಕೃಷಿ ಸಲಹೆಗಳನ್ನು ಪಡೆಯುತ್ತಾರೆ",
    "Receive localized weather alerts, neural quality grading, and 7-day Mandi modal price trajectories.": "ಸ್ಥಳೀಯ ಹವಾಮಾನ ಅಪಾಯಗಳು, ಗುಣಮಟ್ಟ ವಿಶ್ಲೇಷಣೆ ಮತ್ತು 7-ದಿನಗಳ ಮಂಡಿ ಬೆಲೆ ಮುನ್ಸೂಚನೆಯನ್ನು ಪಡೆಯುತ್ತಾರೆ.",
    "Lists Produce for Sale": "ಮಾರಾಟಕ್ಕೆ ಬೆಳೆಯನ್ನು ಪಟ್ಟಿ ಮಾಡುತ್ತಾರೆ",
    "Publish produce lots with verified AI grade, asking price per kg, minimum lot, and pickup location.": "ಎಐ ಗ್ರೇಡ್, ನಿರೀಕ್ಷಿತ ಬೆಲೆ, ಕನಿಷ್ಠ ಪ್ರಮಾಣ ಮತ್ತು ಸ್ಥಳದೊಂದಿಗೆ ಬೆಳೆಯನ್ನು ಪಟ್ಟಿ ಮಾಡುತ್ತಾರೆ.",
    "Buyer Discovers & Orders": "ಖರೀದಿದಾರರು ನೋಡಿ ಆರ್ಡರ್ ಮಾಡುತ್ತಾರೆ",
    "Institutional buyers compare listings against live APMC benchmarks and place escrow-protected purchase orders.": "ಸಗಟು ಖರೀದಿದಾರರು ಮಂಡಿ ಬೆಲೆಗಳೊಂದಿಗೆ ಹೋಲಿಸಿ ಎಸ್ಕ್ರೋ ರಕ್ಷಣೆಯೊಂದಿಗೆ ಆರ್ಡರ್ ಮಾಡುತ್ತಾರೆ.",
    "Settlement & Delivery": "ಪಾವತಿ ಬಿಡುಗಡೆ ಮತ್ತು ವಿತರಣೆ",
    "Upon delivery QA inspection sign-off, escrow automatically releases direct bank transfer to the farmer.": "ಗುಣಮಟ್ಟ ಪರಿಶೀಲನೆಯ ನಂತರ ಎಸ್ಕ್ರೋ ನೇರವಾಗಿ ರೈತರ ಬ್ಯಾಂಕ್ ಖಾತೆಗೆ ಹಣ ವರ್ಗಾಯಿಸುತ್ತದೆ.",
    "Platform Ecosystem Metrics & Benchmarks": "ವೇದಿಕೆಯ ಪರಿಸರ ವ್ಯವಸ್ಥೆಯ ಮಾಪನಗಳು",
    "Transparent disclosure of simulated test partitions and verified production benchmarks.": "ಪಾರದರ್ಶಕ ಬಹಿರಂಗಪಡಿಸುವಿಕೆ ಮತ್ತು ದೃಢೀಕೃತ ವಹಿವಾಟು ಮಾನದಂಡಗಳು.",
    "Full Vernacular Speech & Language System (8 Indian Languages)": "ಸಂಪೂರ್ಣ 8 ಭಾರತೀಯ ಭಾಷೆಗಳ ಧ್ವನಿ ಮತ್ತು ಭಾಷಾ ವ್ಯವಸ್ಥೆ",
    "No typing needed in the field. Speak naturally in your native language. The AI Assistant listens, translates, and replies with voice.": "ಹೊಲದಲ್ಲಿ ಟೈಪ್ ಮಾಡುವ ಅಗತ್ಯವಿಲ್ಲ. ನಿಮ್ಮ ಮಾತೃಭಾಷೆಯಲ್ಲೇ ಸಹಜವಾಗಿ ಮಾತನಾಡಿ. ಎಐ ಸಹಾಯಕ ಆಲಿಸಿ ಧ್ವನಿಯಲ್ಲೇ ಉತ್ತರಿಸುತ್ತದೆ.",
    "Ready to Experience the Future of Agricultural Commerce?": "ಕೃಷಿ ವಾಣಿಜ್ಯದ ಭವಿಷ್ಯವನ್ನು ಅನುಭವಿಸಲು ಸಿದ್ಧರಿದ್ದೀರಾ?",
    "Join thousands of verified farmers and institutional buyers getting fair prices, transparent escrow, and AI intelligence.": "ನ್ಯಾಯಯುತ ಬೆಲೆ, ಪಾರದರ್ಶಕ ಎಸ್ಕ್ರೋ ಮತ್ತು ಎಐ ಬುದ್ಧಿಮತ್ತೆಯನ್ನು ಪಡೆಯುತ್ತಿರುವ ಸಾವಿರಾರು ರೈತರೊಂದಿಗೆ ಸೇರಿ.",
    "Start Talking with AgriAI": "ಅಗ್ರಿ-ಎಐ ಜೊತೆ ಮಾತನಾಡಲು ಪ್ರಾರಂಭಿಸಿ",
    "Sign in to your account": "ನಿಮ್ಮ ಖಾತೆಗೆ ಲಾಗಿನ್ ಮಾಡಿ",
    "Enter your credentials to access your personalized agricultural trading portal.": "ನಿಮ್ಮ ವೈಯಕ್ತಿಕಗೊಳಿಸಿದ ಕೃಷಿ ವ್ಯಾಪಾರ ಪೋರ್ಟಲ್ ಅನ್ನು ಪ್ರವೇಶಿಸಲು ನಿಮ್ಮ ವಿವರಗಳನ್ನು ನಮೂದಿಸಿ.",
