    "Discover verified farmer listings, compare APMC modal benchmarks, request bulk orders, and trade with locked escrow protection.": "सत्यापित किसानों की सूची देखें, एपीएमसी दरों की तुलना करें, थोक खरीद का अनुरोध करें और एस्क्रो सुरक्षा के साथ ऑर्डर करें।",
