    "AI Agricultural Intelligence Showcase": "एआई कृषि बुद्धिमत्ता प्रदर्शन",
    "Our forecasting models calculate predictions from historical observations while Gemini explains them with complete transparency.": "हमारे पूर्वानुमान मॉडल ऐतिहासिक मंडी डेटा से गणना करते हैं और जेमिनी उन्हें पूरी पारदर्शिता के साथ समझाता है।",
    "How AgriTech Works": "एग्रीटेक कैसे काम करता है",
    "From planting through AI harvest guidance, verified listing, procurement, and automated escrow bank settlements.": "बुवाई से लेकर एआई कटाई मार्गदर्शन, सत्यापित लिस्टिंग, थोक खरीद और सीधे बैंक एस्क्रो निपटान तक।",
