    "Batch Grade: Grade A (Export Quality)": "లాట్ నాణ్యత: గ్రేడ్ A (ఎగుమతి నాణ్యత)",
    "Manage crops, predict mandi prices, obtain agronomic guidance, and sell directly with zero middleman deductions.": "పంటలను నిర్వహించండి, మండీ ధరలను అంచనా వేయండి, శాస్త్రీయ మార్గదర్శకత్వం పొందండి మరియు దళారుల ప్రమేయం లేకుండా నేరుగా విక్రయించండి.",
    "Discover verified farmer listings, compare APMC modal benchmarks, request bulk orders, and trade with locked escrow protection.": "ధృవీకరించబడిన రైతుల ఉత్పత్తులను కనుగొనండి, APMC మార్కెట్ ధరలను సరిపోల్చండి, బల్క్ ఆర్డర్లు చేయండి మరియు ఎస్క్రో రక్షణతో కొనుగోలు చేయండి.",
    "Supervise marketplace activities, verify farmer KYC & buyer licenses, audit disputes, and monitor AI model health.": "మార్కెట్ కార్యకలాపాలను పర్యవేక్షించండి, రైతుల KYC & కొనుగోలుదారుల లైసెన్స్‌లను ధృవీకరించండి మరియు AI పనితీరును సమీక్షించండి.",
    "AI Agricultural Intelligence Showcase": "ఏఐ వ్యవసాయ మేధస్సు ప్రదర్శన",
    "Our forecasting models calculate predictions from historical observations while Gemini explains them with complete transparency.": "మా ధరల అంచనా నమూనాలు చారిత్రక డేటాను విశ్లేషిస్తాయి మరియు జెమిని AI స్పష్టమైన వివరణలను అందిస్తుంది.",
    "How AgriTech Works": "అగ్రిటెక్ ఎలా పనిచేస్తుంది",
    "From planting through AI harvest guidance, verified listing, procurement, and automated escrow bank settlements.": "విత్తనం నాటినప్పటి నుండి AI కోత సలహా, ధృవీకరించబడిన లిస్టింగ్, కొనుగోలు మరియు ఆటోమేటెడ్ ఎస్క్రో బ్యాంక్ చెల్లింపుల వరకు.",
    "Farmer Registers": "రైతు నమోదు",
    "Create a farmer profile with land acreage, soil type, and regional language preference.": "భూమి విస్తీర్ణం, నేల రకం మరియు భాషా ప్రాధాన్యతతో రైతు ప్రొఫైల్‌ను సృష్టించండి.",
    "Adds Crops & Harvests": "పంటలు & దిగుబడి నమోదు",
    "Log crop varieties, sowing dates, and expected yield windows into the farm management tracker.": "పంట రకాలు, విత్తిన తేదీలు మరియు అంచనా దిగుబడి వివరాలను నమోదు చేయండి.",
    "Receives AI Insights": "AI విశ్లేషణల స్వీకరణ",
    "Receive localized weather alerts, neural quality grading, and 7-day Mandi modal price trajectories.": "స్థానిక వాతావరణ హెచ్చరికలు, నాణ్యత గ్రేడింగ్ మరియు 7-రోజుల మండీ ధరల అంచనాలను పొందండి.",
    "Lists Produce for Sale": "ఉత్పత్తిని అమ్మకానికి పెట్టండి",
    "Publish produce lots with verified AI grade, asking price per kg, minimum lot, and pickup location.": "AI గ్రేడ్, కిలో ధర, కనీస లాట్ పరిమాణం మరియు పిక్-అప్ స్థానంతో పంటను ప్రచురించండి.",
    "Buyer Discovers & Orders": "కొనుగోలుదారు ఆర్డర్",
    "Institutional buyers compare listings against live APMC benchmarks and place escrow-protected purchase orders.": "వ్యాపారులు నాణ్యతను తనిఖీ చేసి, ఎస్క్రో రక్షణతో కొనుగోలు ఆర్డర్‌లను ఉంచుతారు.",
    "Settlement & Delivery": "డెలివరీ & తక్షణ చెల్లింపు",
    "Upon delivery QA inspection sign-off, escrow automatically releases direct bank transfer to the farmer.": "నాణ్యత ధృవీకరణ పూర్తయిన వెంటనే ఎస్క్రో ద్వారా రైతు బ్యాంక్ ఖాతాకు నేరుగా డబ్బు జమ అవుతుంది.",
    "Platform Ecosystem Metrics & Benchmarks": "వేదిక కొలమానాలు మరియు బెంచ్‌మార్కులు",
