    "Full Vernacular Speech & Language System (8 Indian Languages)": "పూర్తి ప్రాంతీయ వాయిస్ & భాషా వ్యవస్థ (8 భారతీయ భాషలు)",
    "No typing needed in the field. Speak naturally in your native language. The AI Assistant listens, translates, and replies with voice.": "పొలంలో టైప్ చేయాల్సిన పనిలేదు. మీ మాతృభాషలో సహజంగా మాట్లాడండి. AI అసిస్టెంట్ విని, సమాధానాన్ని వాయిస్ రూపంలో చెబుతుంది.",
    "Ready to Experience the Future of Agricultural Commerce?": "వ్యవసాయ వాణిజ్య భవిష్యత్తును అనుభవించడానికి సిద్ధంగా ఉన్నారా?",
