    "Manage crops, predict mandi prices, obtain agronomic guidance, and sell directly with zero middleman deductions.": "பயிர்களை நிர்வகிக்கவும், மண்டி விலையைக் கணிக்கவும், இடைத்தரகர்கள் இல்லாமல் நேரடியாக விற்கவும்.",
    "Discover verified farmer listings, compare APMC modal benchmarks, request bulk orders, and trade with locked escrow protection.": "சரிபார்க்கப்பட்ட விவசாயிகளிடமிருந்து நேரடியாக கொள்முதல் செய்து எஸ்க்ரோ பாதுகாப்புடன் வர்த்தகம் செய்யுங்கள்.",
    "Supervise marketplace activities, verify farmer KYC & buyer licenses, audit disputes, and monitor AI model health.": "தள மேற்பார்வை, KYC சரிபார்ப்பு மற்றும் மோசடி தடுப்பு கட்டளை மையம்.",
