    "Full Vernacular Speech & Language System (8 Indian Languages)": "പൂർണ്ണ പ്രാദേശിക വോയ്‌സ് & ഭാഷാ സംവിധാനം (8 ഇന്ത്യൻ ഭാഷകൾ)",
    "No typing needed in the field. Speak naturally in your native language. The AI Assistant listens, translates, and replies with voice.": "പാടത്ത് നിന്ന് ടൈപ്പ് ചെയ്യേണ്ടതില്ല. നിങ്ങളുടെ മാതൃഭാഷയിൽ സംസാരിക്കുക. AI അസിസ്റ്റന്റ് കേട്ട് മനസ്സിലാക്കി ശബ്ദത്തിൽ മറുപടി നൽകുന്നു.",
    "Ready to Experience the Future of Agricultural Commerce?": "കാർഷിക വാണിജ്യത്തിന്റെ ഭാവി അനുഭവിക്കാൻ തയ്യാറാണോ?",
